import {ESTATE_WORLDS,estateMap,estateOffer,estateAssets,estateWorth} from './estate-core.mjs';
import {account,accountReady,mountAccount} from './account.mjs';
import {activeRefProof,nativePolicyResult} from './ref-reader.mjs';
const world=Number(new URL(location.href).searchParams.get('world')||2),w=ESTATE_WORLDS[world]||ESTATE_WORLDS[2],$=s=>document.querySelector(s);let lang=localStorage.getItem('moneyLabLanguage')==='en'?'en':'vi',profile=null,room=null,selected=1,busy=false,error='',proofText='',step=0;
let key=localStorage.getItem('moneyLabOnlinePlayer.v1');if(!/^ml_[a-f0-9]{64}$/.test(key||'')){key='ml_'+[...crypto.getRandomValues(new Uint8Array(32))].map(n=>n.toString(16).padStart(2,'0')).join('');localStorage.setItem('moneyLabOnlinePlayer.v1',key);}
const t=(a,b)=>lang==='vi'?a:b,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'$'+Math.round(n||0).toLocaleString('en-US'),uid=()=>[...crypto.getRandomValues(new Uint8Array(12))].map(n=>n.toString(16).padStart(2,'0')).join(''),btn=(label,a,disabled=false)=>`<button data-a="${a}" ${busy||disabled?'disabled':''}>${label}</button>`;
async function api(path,body){const r=await fetch('/api/estate/'+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+key,...(account?{'X-MoneyLab-Wallet':'1'}:{}),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify({...body,world:w.id,requestId:body.requestId||uid()})}:{})});const d=await r.json();if(!r.ok)throw Error(d.error);d.offset=(d.serverNow||Date.now())-Date.now();return d;}
const messages={HUB_THRESHOLD:['Chưa đủ HUB tích lũy để vào World này.','Your accumulated HUB does not meet this world’s threshold.'],ALREADY_IN_ROOM:['Hãy hoàn thành và rời phòng hiện tại trước.','Finish and leave your current room first.'],FINISH_SOLO_FIRST:['Hoàn thành hoặc bỏ chặng Solo trước khi vào phòng.','Finish or abandon your Solo stage first.'],WAIT_FOR_ALL_READY:['Chờ đủ người và tất cả bấm Sẵn sàng.','Wait for a full room and everyone to be ready.'],ROOM_CHANGED_REFRESH:['Phòng vừa thay đổi, đã tải lại. Thử lại thao tác.','Room changed and was refreshed. Retry your action.'],SURRENDER_AND_WAIT_FOR_MATCH:['Bỏ lượt đầu tư của bạn rồi đợi trận kết thúc để rời phòng.','Surrender your investment stage and wait for the match to finish before leaving.'],INVALID_ACTION:['Chưa đến lượt, thiếu vốn hoặc thao tác không phù hợp.','Not your turn, insufficient capital or invalid action.'],ESTATE_UNAVAILABLE:['Chưa đồng bộ được phòng. Thử lại sau.','Room sync is unavailable. Retry shortly.']};
function render(){const entering=!!room?.game?.active&&!document.body.classList.contains('estate-playing');document.body.classList.toggle('estate-playing',!!room?.game?.active);document.documentElement.lang=lang;$('#worldKicker').textContent='MONEY LAB / WORLD '+w.id;$('#worldTitle').textContent=w.id===2?t('Từ quản lý tiền. Đến làm chủ tài sản.','From managing money. To owning assets.'):t('Quy mô lớn hơn. Trách nhiệm lớn hơn.','Bigger scale. Greater responsibility.');$('#worldIntro').textContent=t(`Bản đầu · Khu du lịch ${w.size} × ${w.size}, ${w.cells} ô. ${w.minPlayers}–6 nhà đầu tư cùng xây một điểm đến.`,`First playable version · ${w.size} × ${w.size}, ${w.cells} spaces. ${w.minPlayers}–6 investors build a destination together.`);$('#entryBadge').innerHTML=`<b>${w.id===2?'> 1,000':'≥ 10,000'} HUB</b><span>${t('Điều kiện HUB tích lũy','Accumulated HUB requirement')}</span><small>${t('Tối thiểu','Minimum')} ${w.minPlayers} ${t('người','players')}</small>`;
 $('#disclosure').innerHTML=t('HUB hiện là điểm giả lập. Điều kiện vào phòng chỉ kiểm tra số dư HUB máy chủ, không thu phí hay trừ HUB. USD trên bàn cờ là ngân sách đầu tư giả định, hoàn toàn tách HUB. Bản này chưa trả thưởng HUB và chưa có cược World 2/3. Mua hoặc trao đổi HUB là hướng nghiên cứu tương lai, chưa triển khai và không cam kết giá trị.','HUB is fictional credit. Entry checks your server HUB balance without charging or deducting HUB. Board USD is a separate simulated investment budget. This version has no World 2/3 HUB rewards or wagers. HUB purchases or trading are future research, not implemented or a promise of value.');
 $('#estateStatus').textContent=busy?t('Đang đồng bộ…','Syncing…'):error?(messages[error]?.[lang==='vi'?0:1]||error):proofText;
 if(!room){$('#estateLobby').innerHTML=`<section class="estate-lobby"><div><p class="eyebrow">${t('HỒ SƠ CỦA BẠN','YOUR PROFILE')}</p><h2>${profile?profile.balance.toLocaleString('en-US'):'…'} HUB <small>${t('máy chủ','server balance')}</small></h2><p>${profile?.eligible?t('Đã đủ điều kiện vốn HUB.','Your HUB qualifies.'):t('Tích lũy thêm HUB tại World 1. Bạn vẫn có thể xem bản đồ và thử quy trình dự án bên dưới.','Build HUB in World 1. You can still explore the map and project walkthrough below.')}</p><p>${t('Đăng nhập ví để dùng chung HUB Solo/Online giữa các thiết bị. HUB Solo chơi khách trên trình duyệt không tự chuyển vào hồ sơ máy chủ.','Sign in with a wallet for shared Solo/Online HUB across devices. Browser-only guest Solo HUB does not migrate into the server profile.')}</p>${profile?.roomCode?`<p>${t('Phòng hiện tại','Current room')}: ${esc(profile.roomCode)}</p><a href="${profile.roomCode.startsWith('W')?'./world.html?world='+profile.roomCode[1]:'./online.html'}">${t('Trở lại phòng','Return to room')} →</a>`:''}</div><div class="estate-room-form"><label>${t('Tên nhà đầu tư','Investor name')}<input id="investorName" maxlength="24" value="${esc(localStorage.getItem('moneyLabOnlineName')||'')}"></label><label>${t('Số người','Players')}<select id="capacity">${Array.from({length:7-w.minPlayers},(_,i)=>w.minPlayers+i).map(n=>`<option>${n}</option>`).join('')}</select></label>${btn(t('Tạo phòng World ','Create World ')+w.id,'create',!profile?.eligible||!!profile?.roomCode)}<div class="estate-join"><label>${t('Mã phòng','Room code')}<input id="roomCode" placeholder="W${w.id}-…" value="${esc(new URL(location.href).searchParams.get('room')||'')}" maxlength="11"></label>${btn(t('Vào phòng','Join room'),'join',!profile?.eligible||!!profile?.roomCode)}</div></div></section>`;}else{const g=room.game;$('#estateLobby').innerHTML=`<section class="estate-room-head"><div><b>${room.code}</b><span>WORLD ${room.world} · ${room.members.length}/${room.capacity}</span></div>${btn(t('Sao chép link mời','Copy invite link'),'invite')}<div class="estate-members">${room.members.map((m,i)=>`<span class="${g?.active&&g.turn===m.seat?'current':''}">${esc(m.name)}${i===room.seat?t(' (Bạn)',' (You)'):''} · ${g?g.players[m.seat]?.finished?t('Đã kết thúc','Finished'):t('Trong trận','In match'):m.ready?'✓':t('Chờ sẵn sàng','Not ready')}</span>`).join('')}</div>${!g?btn(room.members[room.seat].ready?t('Hủy sẵn sàng','Not ready'):t('Sẵn sàng','Ready'),'ready')+(room.isHost?btn(t('Bắt đầu đầu tư','Start investing'),'start',room.members.length!==room.capacity||!room.members.every(m=>m.ready)):''):''}${!g||g.done?btn(t('Rời phòng','Leave room'),'leave'):''}</section>`;}
 const g=room?.game,p=g?.players[room.seat];$('#estateApp').innerHTML=`${g?gameStats(g,p):`<div class="estate-preview-label">${t('XEM TRƯỚC · Không tạo lượt chơi, không cấp hoặc tiêu HUB','PREVIEW · No game run, HUB grant or HUB spending')}</div>`}<div class="estate-layout"><section class="estate-map-panel"><div class="estate-map-title"><strong>${t('KHU DU LỊCH MONEY BAY','MONEY BAY TOURISM DISTRICT')}</strong><span>${w.cells} ${t('ô quy hoạch','zoned spaces')}</span></div><div class="estate-board" style="--map-size:${w.size}">${estateMap(w.id).map((tile,i)=>{const owned=g?.properties[i],row=Math.floor(i/w.size),col=row%2?w.size-i%w.size:i%w.size+1;return `<button data-cell="${i}" style="grid-row:${row+1};grid-column:${col}" class="estate-cell ${i===selected?'selected':''} ${tile.kind} ${owned?'owned stage-'+owned.stage:''}"><small>${String(i+1).padStart(2,'0')}</small><span class="estate-icon">${tile.icon}</span><strong>${esc(tile.name[lang==='vi'?0:1])}</strong><em>${owned?esc(g.players[owned.owner].name)+' · '+owned.stage+'/3':tile.kind==='land'?money(tile.land):''}</em>${g?`<span class="estate-pawns">${g.players.flatMap((x,n)=>x.position===i?[`<i style="--seat:${['#246c54','#c08b3e','#687fa7','#9c6d98','#ad624e','#4c9297'][n]}">${n+1}</i>`]:[]).join('')}</span>`:''}</button>`;}).join('')}</div><p class="estate-map-note">${t('Di chuyển theo số ô; cuối tuyến quay về cổng. Màu đất và dấu 1/3–3/3 thể hiện chủ sở hữu và tiến độ.','Follow numbered spaces; the route loops back to the gateway. Ownership and 1/3–3/3 markers show project progress.')}</p></section><aside class="estate-project">${g?decision(g):projectCard(estateMap(w.id)[selected])}</aside></div>${g?holdings(g,room.seat):''}${room?.ranking?`<section class="estate-ranking"><h2>${t('Bảng xếp hạng cuối chặng','Final stage ranking')}</h2><p>${t('Ưu tiên người không thiếu thanh khoản, sau đó xét tài sản ròng. Không cộng/trừ HUB ở phiên bản này.','Solvent finishers rank first, then net worth. This version does not add or deduct HUB.')}</p>${room.ranking.map((r,i)=>`<p>${i+1}. ${esc(r.name)} · ${money(r.worth)} · ${r.survived?'✓':t('Thiếu thanh khoản / bỏ chặng','Shortfall / surrendered')}</p>`).join('')}${room.isHost?btn(t('Mở chặng mới cùng phòng','Open another stage in this room'),'next'):''}</section>`:''}${g?`<details class="estate-journal"><summary>${t('Nhật ký đầu tư','Investment journal')}</summary>${g.log.map(r=>`<p>${esc(g.players[r.seat]?.name)} · ${t('Tháng','Month')} ${r.month}: ${esc(r.text[lang==='vi'?0:1])}</p>`).join('')}</details>`:''}`;
 if(entering)requestAnimationFrame(()=>$('#estateApp').scrollIntoView({block:'start'}));
 $('#rulesTitle').textContent=t('Luật World ','World ')+w.id+t(' · Bản đầu',' · Initial rules');$('#estateRules').innerHTML=`<ol>${(lang==='vi'?[
 `${w.minPlayers}–6 người, tất cả có ${w.id===2?'trên 1.000':'ít nhất 10.000'} HUB máy chủ và sẵn sàng. Không thu HUB khi vào phòng.`,
 `Mỗi người có ${money(w.cash)} tiền mặt, ${money(w.reserve)} dự phòng và ${money(w.debt)} nợ. Lương ${money(w.salary)}, sinh hoạt ${money(w.living)}, trả nợ tối đa ${money(w.payment)} mỗi tháng.`,
 `Mỗi lượt là một tháng, tối đa 60 giây. Chặng dài ${w.months} tháng/người. Gieo 1–6 ô, không quay lại. Hết giờ tự gieo nếu cần, bỏ đầu tư/khoản thu tự nguyện, vẫn xử lý nghĩa vụ và thị trường.`,
 'Đất có quy hoạch cố định. Lần dừng 1: mua đất, cần vốn tối thiểu để dự trù cả đợt xây đầu. Lần dừng 2 trên đất của mình: góp 60% vốn xây. Lần dừng 3: trả 40% còn lại, hoàn công và khai thác từ tháng kế tiếp của mình.',
 'Công trình đã mở tạo doanh thu mỗi tháng của chủ sở hữu, đồng thời chịu chi phí vận hành và mùa du lịch. Người khác dừng vào công trình đã mở phải trả phí dịch vụ. Đất trống/đang xây chưa thu phí. Không có lựa chọn mua lại đất của đối thủ.',
 'Mùa du lịch đổi hệ số doanh thu toàn khu. Biến cố có chi phí sửa chữa bắt buộc hoặc hỗ trợ tự nguyện. Hóa đơn dùng tiền mặt rồi dự phòng; thiếu thanh khoản kết thúc chặng của người đó, không xóa nợ.',
 'Giá tài sản tính theo vốn đất và vốn xây đã góp, chưa định giá thị trường. Phiên bản đầu chưa có bán đất, vay mới, đấu giá, chuyển nhượng, cược hoặc thưởng HUB World 2/3. Các phần này sẽ phát triển tiếp.',
 'Đối chiếu TapeOut là kiểm tra minh họa các tín hiệu dự phòng, nghĩa vụ và tỷ lệ trả nợ do Money Lab tính. Không chứng minh toàn bộ ván, không bảo đảm lợi nhuận. Trạng thái World 2/3 được lưu tại máy chủ, chưa lưu trên blockchain.'
 ]:[`${w.minPlayers}–6 ready players; all need ${w.id===2?'more than 1,000':'at least 10,000'} server HUB. No HUB is charged for entry.`,`Start with ${money(w.cash)} cash, ${money(w.reserve)} reserves and ${money(w.debt)} debt. Salary ${money(w.salary)}, living ${money(w.living)}, debt payment up to ${money(w.payment)} monthly.`,`One turn is one month, capped at 60 seconds, for ${w.months} months per player. Roll 1–6 spaces. Timeout auto-rolls if needed and declines optional choices while bills and markets still apply.`,'Zoning is fixed. First landing: buy land with enough cash to plan the first construction tranche. Second landing on your own land: fund 60% of construction. Third: pay the remaining 40%, complete and open from your next month.','Open projects earn monthly revenue and incur operating costs and tourism demand risk. Visitors pay a service fee only on open projects. Empty or unfinished land charges no fee. Opponent-owned land cannot be bought.','Tourism seasons affect the whole district. Business events include mandatory repairs or optional support. Bills use cash then reserves; a shortfall ends that investor’s stage without erasing debt.','Asset values use contributed land/construction cost, not market prices. This initial version has no land sales, new loans, auctions, transfers, World 2/3 wagers or HUB rewards. These can be developed later.','TapeOut comparison checks illustrative reserve, obligation and debt-ratio signals computed by Money Lab. It does not prove the entire game or guarantee profit. World 2/3 state is server-saved, not onchain.']).map(s=>`<li>${s}</li>`).join('')}</ol>`;}
function gameStats(g,p){return `<div class="estate-stats">${[[t('Tiền mặt','Cash'),money(p.cash)],[t('Dự phòng','Reserve'),money(p.reserve)],[t('Nợ còn lại','Debt'),money(p.debt)],[t('Tài sản ròng','Net worth'),money(estateWorth(g,room.seat))],[t('Tháng','Month'),p.month+' / '+w.months]].map(([a,b])=>`<div><small>${a}</small><strong>${b}</strong></div>`).join('')}</div>`;}
function projectCard(tile){if(tile.kind!=='land')return `<span class="estate-project-icon">${tile.icon}</span><h2>${esc(tile.name[lang==='vi'?0:1])}</h2><p>${t('Ô chung của khu du lịch. Các sự kiện vẫn chịu giới hạn lượt và được ghi vào nhật ký. Chọn một ô đất để xem quy hoạch và ba bước đầu tư.','A shared district space. Events respect turn limits and are recorded. Select a land plot to inspect its zoning and three investment stages.')}</p>`;return `<p class="eyebrow">${t('QUY HOẠCH CỐ ĐỊNH','FIXED ZONING')} · ${tile.index+1}</p><span class="estate-project-icon">${tile.icon}</span><h2>${esc(tile.name[lang==='vi'?0:1])}</h2><p>${t('Vốn tối thiểu để bắt đầu','Minimum planning capital')}: <b>${money(tile.minimum)}</b></p><div class="estate-stages">${[[t('Mua đất','Buy land'),tile.land],[t('Góp vốn xây · 60%','Fund construction · 60%'),tile.build*.6],[t('Hoàn công · 40%','Complete and open · 40%'),tile.build*.4]].map(([name,cost],i)=>`<div class="${step===i?'highlight':''}"><b>${i+1}</b><span>${name}<strong>${money(cost)}</strong></span></div>`).join('')}</div><p>${t('Tổng vốn đất + xây','Total land + construction')}: ${money(tile.land+tile.build)}</p><div class="estate-project-economics"><span>${t('Doanh thu cơ sở/tháng','Base monthly revenue')}<b>${money(tile.revenue)}</b></span><span>${t('Chi phí vận hành/tháng','Monthly operating cost')}<b>−${money(tile.operating)}</b></span></div><p class="estate-fine">${t('Doanh thu thực tế trong game thay đổi theo mùa và nhu cầu. Công trình bắt đầu sinh dòng tiền từ lượt tháng kế tiếp sau hoàn công.','Actual game revenue varies with seasons and demand. Cash flow starts on the owner’s next monthly turn after opening.')}</p>${!room?.game?btn(t('Xem bước kế tiếp · chỉ minh họa','Next stage · illustration only'),'preview-step'):''}`;}
function decision(g){const p=g.players[room.seat],current=g.players[g.turn];if(g.done)return `<h2>${t('Chặng đầu tư đã kết thúc','Investment stage finished')}</h2><p>${t('Xem bảng xếp hạng và nhật ký phía dưới.','See the ranking and journal below.')}</p>`;if(g.turn!==room.seat)return `<p class="eyebrow">${t('ĐANG CHỜ','WAITING')}</p><h2>${esc(current.name)}</h2><p>${t('Đang đến lượt nhà đầu tư này. Mỗi lượt tối đa 60 giây.','This investor is taking their turn. Each turn lasts at most 60 seconds.')}</p><p data-estate-deadline="${g.deadline}"></p>`;const offer=estateOffer(g),tile=estateMap(g.world)[p.position];return `<p class="eyebrow">${t('LƯỢT CỦA BẠN','YOUR TURN')}</p><div class="estate-timer" data-estate-deadline="${g.deadline}">60s</div><h2>${esc(tile.name[lang==='vi'?0:1])}</h2>${p.last?`<div class="estate-monthly"><b>${t('Dòng tiền tháng vừa xử lý','Monthly cash flow processed')}</b><span>${t('Lương + doanh thu','Salary + revenue')}: ${money(p.last.salary+p.last.revenue)}</span><span>${t('Sinh hoạt + trả nợ + vận hành','Living + debt + operations')}: −${money(p.last.living+p.last.principal+p.last.operating)}</span>${p.last.unpaid?`<strong>${t('Chưa thanh toán','Unpaid')}: ${money(p.last.unpaid)}</strong>`:''}</div>`:''}${!g.rolled?btn(t('Gieo xúc xắc','Roll dice'),'act:roll'):`<p>${t('Xúc xắc','Dice')}: ${g.pending.die}</p>${offer&&['land','build','open'].includes(offer.action)?`<p>${t('Bước đầu tư','Investment step')}: <b>${{land:t('Mua đất','Buy land'),build:t('Góp vốn xây','Fund construction'),open:t('Hoàn công','Complete and open')}[offer.action]}</b> · ${money(offer.cost)}</p><p>${t('Tiền mặt sau đầu tư','Cash after investment')}: ${money(p.cash-offer.cost)}</p>${btn(t('Xác nhận đầu tư','Confirm investment'),'act:invest',!offer.affordable)}${btn(t('Bỏ qua','Pass'),'act:pass')}<div class="estate-fine" id="estateRisk">${riskText(g,offer.cost)}</div>${btn(t('Đối chiếu với TapeOut','Compare with TapeOut'),'risk')}`:g.pending.windfall?btn(t('Nhận hỗ trợ ','Collect support ')+money(g.pending.windfall),'act:collect')+btn(t('Từ chối','Decline'),'act:pass'):btn(t('Kết thúc lượt','Finish turn'),'act:continue')}`}${btn(t('Bỏ chặng của tôi','Surrender my stage'),'act:surrender')}<details><summary>${t('Quy hoạch ô đang xem','Selected plot plan')}</summary>${projectCard(estateMap(w.id)[selected])}</details>`;}
function signals(g,cost){const p=g.players[room.seat],operating=estateAssets(g,room.seat).filter(a=>a.stage===3).reduce((n,a)=>n+a.operating,0);return {reserve:Number(p.reserve>=w.living),coverage:Number(p.cash-cost+p.reserve+w.salary>=w.living+Math.min(p.debt,w.payment)+operating),installments:Number(Math.min(p.debt,w.payment)<=w.salary*.3)};}
function riskText(g,cost){const s=signals(g,cost);return t('Tín hiệu Money Lab tính: ','Signals computed by Money Lab: ')+`R=${s.reserve}, C=${s.coverage}, D=${s.installments}. `+t('Chưa phải bằng chứng đọc chain; không bảo đảm có lãi.','Not a chain-read proof; not a profit guarantee.');}
function holdings(g,seat){return `<section class="estate-holdings"><h2>${t('Danh mục dự án của bạn','Your project portfolio')}</h2>${estateAssets(g,seat).length?estateAssets(g,seat).map(a=>`<article><b>${a.icon} ${esc(a.name[lang==='vi'?0:1])}</b><span>${t('Tiến độ','Stage')} ${a.stage}/3 · ${t('Vốn đã góp','Contributed')}: ${money(a.land+(a.stage>=2?a.build*.6:0)+(a.stage===3?a.build*.4:0))}</span><span>${a.stage===3?t('Đã khai thác','Operating')+' · '+t('doanh thu cơ sở','base revenue')+' '+money(a.revenue):t('Chưa có doanh thu','No revenue yet')}</span></article>`).join(''):`<p>${t('Chưa sở hữu dự án.','No projects owned yet.')}</p>`}</section>`;}
async function refresh(){profile=await api('profile?world='+w.id);if(profile.roomCode?.startsWith('W'+w.id+'-'))room=await api('room?world='+w.id+'&code='+profile.roomCode);render();}
async function act(a){if(busy)return;if(a==='preview-step'){step=(step+1)%3;render();return;}if(a==='invite'){const u=new URL(location.href);u.searchParams.set('room',room.code);try{await navigator.clipboard.writeText(u.href);proofText=t('Đã sao chép link mời.','Invite copied.');}catch{proofText=u.href;}render();return;}
 let path=a,body={code:room?.code,revision:room?.revision};if(a==='create'){body={name:$('#investorName').value,capacity:Number($('#capacity').value)};}if(a==='join')body={name:$('#investorName').value,code:$('#roomCode').value};if(a==='ready')body.ready=!room.members[room.seat].ready;if(a.startsWith('act:')){path='act';body.action=a.slice(4);}busy=true;error='';render();try{if(a==='risk'){const offer=estateOffer(room.game),proof=await activeRefProof();if(!proof)throw Error('REF_NOT_ACTIVE');const result=nativePolicyResult(signals(room.game,offer.cost),proof);proofText=t('Đã đọc TapeOut REF #','TapeOut REF #')+proof.circuitId+' · '+t('khối ','block ')+proof.blockNumber+' · '+(result.output?'PASS':'FAIL')+t('. Chỉ kiểm tra tín hiệu game cung cấp.','. Checks only the signals supplied by the game.');}else{const d=await api(path,body);if(d.left){room=null;profile=await api('profile?world='+w.id);}else {room=d;if(room.game)selected=room.game.players[room.seat].position;}}}catch(e){error=e.message;if(room){try{room=await api('room?world='+w.id+'&code='+room.code);}catch{}}}finally{busy=false;render();}}
document.addEventListener('click',e=>{const cell=e.target.closest('[data-cell]');if(cell){selected=Number(cell.dataset.cell);step=0;render();return;}const a=e.target.closest('[data-a]')?.dataset.a;if(a)act(a);});for(const l of ['vi','en'])$('#'+l).onclick=()=>{lang=l;localStorage.setItem('moneyLabLanguage',l);render();};
mountAccount();render();accountReady.then(refresh).catch(e=>{error=e.message;render();});setInterval(async()=>{if(busy||!room)return;try{const d=await api('room?world='+w.id+'&code='+room.code);if(d.revision!==room.revision){room=d;render();}}catch(e){error=e.message;render();}},2000);setInterval(()=>{for(const el of document.querySelectorAll('[data-estate-deadline]')){const seconds=Math.max(0,Math.ceil((Number(el.dataset.estateDeadline)-Date.now()-(room?.offset||0))/1000));el.textContent=t('Còn ','Time left ')+seconds+'s';el.classList.toggle('urgent',seconds<=10);}},250);
